def coord(degrees,r=1):
    a=degrees*pi/180
    return tuple(round(r*f(a),11) for f in (cos,sin))


def arc(label,angles=(),*,markers=None,edges=(),projections=(),radius=1,scale=4,lines=(),anchors=('A','B','C')):
    """Every edge of the upper arc lies between two measured points on the same circle."""
    vertices={anchors[0]:(radius,0),anchors[1]:(-radius,0),anchors[2]:(0,radius)}
    vertices.update({name:coord(angle,radius) for name,angle in angles})
    vertices.update(markers or {})
    visible_edges=list(edges)
    for name,xprojection in projections:
        x,y=vertices[name];vertices[xprojection]=(x,0)
        visible_edges.append((name,xprojection))
    def raw(p):return tuple(round(scale*z,10) for z in p)
    scaled={name:raw(pos) for name,pos in vertices.items()}
    samples=[raw(coord(a,radius)) for a in range(0,181,5)]
    paths=list(zip(samples,samples[1:]))
    paths.extend([tuple(raw(p) for p in endpoints) for endpoints in lines])
    return graph(label,scaled,edges=visible_edges,lines=paths)


def straight(label,points,eqs,edges=()):
    return graph(label,points,edges=edges,lines=[section(eq,points) for eq in eqs])


def author(n,part,pages,task,answer,hint,steps,views,probes,refs,*,title=None,caption=None):
    opt={'title':title} if title else {}
    c=curve_lesson(n,part=part,pages=pages,question=task,answer=answer,hint=hint,steps=steps,frames=[views[0],*views[:3]],cases=views,prompts=probes,**opt)
    c['source']['chapter']='XII';c['review']['reviewer']='Атанасян 7–9, издание 2023, глава XII, печатные с. '+', '.join(str(x) for x in pages)+'. Определения, знаки, граничные случаи и исходные данные проверены вычислением и измерением собственных моделей.'
    note=caption or 'Единичная полуокружность показана над осью Ox. Длина одной клетки — 1/4. A=(1;0), B=(−1;0), C=(0;1).'
    c['visualization']['caption']=note;c['visualization']['model']['description']=note
    if not title:c['help'][1].update(theoryIds=[f'atanasyan-7-9-theory-{r}-part-1' for r in refs],text='Сверь определение и область допустимых значений с указанными пунктами. Отметь точку и обе её проекции.')
    return c


