def ranges(part):
    def point_at_x(x):return (x,sqrt(1-x*x))
    def points_at_y(y):return [(sqrt(1-y*y),y),(-sqrt(1-y*y),y)]
    if part=='а':
        vals=[.3,1/3,-1/3]
        views=[arc('Абсцисса 0,3',markers={'M':point_at_x(vals[0])},edges=[('O','M')],projections=[('M','H')]),arc('Отрицательная абсцисса −1/3',markers={'M':point_at_x(vals[2])},edges=[('O','M')],projections=[('M','H')]),arc('Новый пример: крайняя допустимая абсцисса −1',[('M',180)],edges=[('O','M')]),arc('Абсцисса 1/3',markers={'M':point_at_x(vals[1])},edges=[('O','M')],projections=[('M','H')]),arc('Линия x=5/3 вне дуги',lines=[((5/3,-.1),(5/3,1.1))]),arc('Линия x=−2,8 вне дуги',lines=[((-2.8,-.1),(-2.8,1.1))])]
        task='Для абсциссы точки верхней единичной полуокружности проверь по порядку 0,3; 1/3; −1/3; 1⅔; −2,8. Укажи все допустимые позиции и объясни границы.'
        answer='Подходят первые три числа. У любой точки x²+y²=1 имеем −1≤x≤1. Обратно, для каждого такого x значение y=√(1−x²) существует и неотрицательно. Числа 5/3 и −2,8 вне диапазона.'
        hint='Отрицательная абсцисса допустима во второй четверти. Сравни каждый x с обоими концами отрезка [−1;1].'
        steps=[('Найди диапазон','Равенство x²+y²=1 даёт x²≤1. При x=0,3 ордината √0,91 неотрицательна, такую точку можно построить. При x=1/3 получаем y=√8/3.','Квадрат абсциссы может равняться 1 на концах диаметра.'),('Проверь отрицательное и выход за границу','При x=−1/3 ордината также √8/3. Число 1⅔=5/3 больше 1, а −2,8 меньше −1. В обоих случаях уравнение y²=1−x² потребовало бы отрицательный квадрат.','Для противоположных абсцисс получаются одинаковые неотрицательные ординаты.'),('Проверь новые крайние значения','При x=−1 существует точка B=(−1;0). При x=1 существует A=(1;0). У x=−1,01 точки уже нет.','Не исключай сами концы допустимого отрезка.')]
        prompts=[('Сколько из пяти исходных абсцисс допустимы?','3','Проверь модули всех пяти чисел.'),('При новом x=−1 какова ордината точки дуги?','0','Из y²=1−1 следует y=0.')];formats=['1;2;3','1; 2; 3','1,2,3','1, 2, 3']
    else:
        y1,y2=.6,1/7;x1,x2=points_at_y(y1),points_at_y(y2)
        views=[arc('Ордината 0,6: две точки',markers={'M':x1[0],'N':x1[1]},lines=[((-1.1,y1),(1.1,y1))]),arc('Отрицательная ордината −0,3',lines=[((-1.1,-.3),(1.1,-.3))]),arc('Новый край: только верхняя точка при y=1',[('M',90)],lines=[((-1.1,1),(1.1,1))]),arc('Ордината 1/7: две точки',markers={'M':x2[0],'N':x2[1]},lines=[((-1.1,y2),(1.1,y2))]),arc('Уровень y=7 выше всей дуги',lines=[((-1,7),(1,7))]),arc('Уровень y=1,002 выше C ровно на 0,002',lines=[((-1.05,1.002),(1.05,1.002))])]
        task='Для ординаты точки верхней единичной полуокружности проверь по порядку 0,6; 1/7; −0,3; 7; 1,002. Укажи все допустимые позиции и объясни свой выбор.'
        answer='Подходят первые два числа. Верхняя полуокружность имеет 0≤y≤1. При любом y из этого отрезка можно взять x=√(1−y²); при 0≤y<1 подходит и противоположная абсцисса. Число −0,3 отрицательно, 7 и 1,002 больше 1.'
        hint='У верхней полуокружности ордината неотрицательна. Сравни 1,002 с 1 точно, без округления.'
        steps=[('Проверь допустимые ординаты','При y=0,6 равенство x²=1−0,36=0,64 даёт x=±0,8. При y=1/7 получаем x=±√48/7. Оба уровня действительно имеют точки на верхней дуге.','Горизонтальная линия может пересекать верхнюю дугу в двух точках.'),('Отдели недопустимые уровни','Отрицательное y=−0,3 лежит ниже Ox. Для 7 и 1,002 имеем y²>1, поэтому x²=1−y² отрицательно. На общем рисунке разность 0,002 меньше одной клетки. Для решения сравни точные числа: 1,002−1=0,002>0.','Условие включает и верхнюю, и нижнюю границу допустимого y.'),('Сравни новые крайние случаи','При y=1 остаётся точка C=(0;1), при y=0 — две конечные точки A=(1;0), B=(−1;0). При y=1,01 решений нет.','Верхняя точка одна, а концы диаметра различны.')]
        prompts=[('Сколько исходных ординат подходят?','2','Оставь значения между 0 и 1 включительно.'),('Сколько точек верхней дуги имеют ординату 1?','1','При y=1 имеем x=0.')];formats=['1;2','1; 2','1,2','1, 2']
    c=author(1098,part,[275],task,answer,hint,steps,views,prompts,[100,101]);c['answer']=dict(mode='exact',accepted=formats,prompt='Введи номера всех допустимых значений по порядку через точку с запятой.',feedback=hint);return c


